181 :         if (type == null) {
182 :             return true;
183 :         }
184 : 
185 :         // only a null type can be assigned to null type which
186 :         // would have cause the previous to return true
187 :         if (toParameterizedType == null) {
188 :             return false;
189 :         }
190 : 
